import {applyPreset, defaults, sizeDesign} from './design.js';
import {scenarios, loadScenario as getExample} from './scenarios.js';
import {icon} from './icons.js';

const number = (x,d=1) => Number.isFinite(x) ? x.toLocaleString('en-US',{maximumFractionDigits:d}) : '—';
const escape = value => String(value ?? '').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const metric = (label, value, unit, help) => ({label,value,unit,help});
const stage = (id,short,title,camera,page,intent) => ({id,short,title,camera,page,intent});
export const chapters = [
  stage('integration','Integration','Will the payload fit?', 'launch','launch','Inspect the folded spacecraft on its adapter and measure clearance against the selected payload envelope.'),
  stage('pad','On the pad','The stack is ready for launch', 'launch','launch','See the integrated launch vehicle on its pad before liftoff.'),
  stage('ascent','Ascent','Ride the launch vehicle', 'launch','launch','Watch the illustrative ascent and the change in altitude before spacecraft separation.'),
  stage('insertion','Insertion','Separate and trim the orbit', 'launch','orbit','Follow release from the upper stage and the spacecraft’s own insertion burn.'),
  stage('commissioning','Commissioning','Bring the spacecraft to life', 'spacecraft','power','Watch stowed appendages deploy and solar generation begin.'),
  stage('operations','Computing','Run the orbital data center', 'core','thermal','Look inside the thermal enclosure as processors send heat through the coolant loop.'),
  stage('contact','Ground pass','Bring the data back to Earth', 'spacecraft','comm','Observe contact acquisition, terminal power and payload leaving the recorder.'),
  stage('reboost','Reboost','Replace the momentum lost to drag', 'spacecraft','prop','Watch a chemical orbit-maintenance burn and read the tank ledger.'),
  stage('desat','CMG unload','Unload the pointing system', 'spacecraft','attitude','Watch the magnetic torquers exchange angular momentum with Earth’s field.'),
  stage('deorbit','Deorbit','Close the mission', 'orbit','prop','Check the reserved propellant, retrograde burn and modeled atmospheric entry interface.'),
];
export const presetList = [
 {id:'pathfinder',name:'Pathfinder',type:'Compact demonstrator',icon:'satellite',design:{...defaults,trayCount:4,solarM2:66,radiatorM2:23,batteryKWh:16,storageTB:4,propellantKg:220}},
 {id:'reference',name:'Reference node',type:'Balanced compute',icon:'cpu',design:{...defaults}},
 {id:'optical',name:'Optical relay',type:'Bulk downlink',icon:'radio',design:{...scenarios.find(s=>s.id==='bulk-optical').design}},
 {id:'carrier',name:'Compute carrier',type:'High-duty compute',icon:'layers-3',design:{...applyPreset(defaults,'launcher','glenn'),trayCount:26,solarM2:390,radiatorM2:132.6,batteryKWh:104,propellantKg:850,storageTB:32,launchAllowanceKg:32000}},
 {id:'scale',name:'10 MW study',type:'Launch-limit case',icon:'rocket',design:{...applyPreset(applyPreset(defaults,'launcher','starship'),'compute','dgx'),trayCount:981,solarM2:86000,radiatorM2:31000,batteryKWh:15000,storageTB:512,propellantKg:45000,launchAllowanceKg:85000}}
].map(p=>({...p,h:sizeDesign(p.design)}));
export const vignettes = [
 {id:'bulk-optical',name:'A pass over Madrid',caption:'Follow 18 TB of queued data into optical contact.',icon:'radio',number:'01',tag:'GROUND LINK',preset:'optical',chapter:'contact',frames:['The recorder is waiting','Acquire the receiver','Transmit, then release']},
 {id:'compute-burst',name:'Heat from a compute burst',caption:'Follow a burst through the cold plate and radiators.',icon:'thermometer-sun',number:'02',tag:'THERMAL LOOP',preset:'burst',chapter:'operations',frames:['Before the burst','Power up the trays','Watch the cooldown']},
 {id:'dawn-dusk',name:'A day without eclipse',caption:'Trace an orbit along the boundary between day and night.',icon:'sun-moon',number:'03',tag:'ORBIT GEOMETRY',preset:'dawn',chapter:'operations',frames:['Find the terminator','Travel one revolution','Read the full day']},
];
export function designName(view){return (presetList.find(p=>p.id===view.preset)?.name||({burst:'Burst demonstrator',dawn:'Dawn–dusk node',custom:'Custom spacecraft'})[view.preset]||'Custom spacecraft')+(view.modified?' · edited':'')}
export const powerLabel=h=>h.itKw>=1000?number(h.itKw/1000,2)+' MW':number(h.itKw,1)+' kW';
export function presetShelf(view){
 return `<section class="presetbank" aria-label="Spacecraft design presets"><div class="bankheading"><span class="guideflag">DESIGN PRESETS</span><span class="bankcaption">Choose a spacecraft</span><button class="bankedit" data-action="hardware" data-tip="Open technology presets, editable design assumptions and sizing targets.">Hardware presets ${icon('sliders-horizontal',13)}</button></div><div class="designstrip">${presetList.map(p=>`<button class="designcard ${p.id===view.preset?'active':''}" data-design="${p.id}" aria-pressed="${p.id===view.preset}" data-tip="${escape('Load '+p.name+' with '+p.h.trays+' compute trays, '+number(p.h.solarM2)+' m² of solar array and '+number(p.h.batteryKWh)+' kWh of battery. Compare at the current mission chapter.')}"><span class="designicon">${icon(p.icon,18)}</span><span><strong>${p.name}</strong><small>${powerLabel(p.h)} <b>·</b> ${number(p.h.storageTB,0)} TB</small></span><i></i></button>`).join('')}</div></section>`;
}
export function guideNav(view){
 const v=vignettes.find(x=>x.id===view.vignette);
 const labels=v ? v.frames.map((l,i)=>({id:String(i),label:l,hint:'Jump to '+l.toLowerCase()+' in this vignette.'})) : chapters.map(c=>({id:c.id,label:c.short,hint:c.intent}));
 const active=v?String(view.beat):view.chapter;
 return `<nav class="flightpath" aria-label="${v?'Vignette scenes':'Mission sequence'}"><div class="pathlabel"><span class="guideflag">${v?'VIGNETTE':'MISSION SEQUENCE'}</span>${v?`<button class="textbutton" data-action="tour-home">All chapters ${icon('chevron-right',11)}</button>`:''}</div><div class="pathscroll"><div class="pathsteps">${labels.map((l,i)=>`<button class="pathstep ${l.id===active?'active':''}" aria-current="${l.id===active?'step':'false'}" data-${v?'beat':'chapter'}="${l.id}" data-tip="${escape(l.hint)}"><i>${String(i+1).padStart(2,'0')}</i><span>${escape(l.label)}</span></button>`).join('')}</div></div></nav>`;
}
export function vignetteShelf(){return `<section class="watchlist"><div class="bankheading"><span class="guideflag">GUIDED VIGNETTES</span><span class="bankcaption">Watch one operation up close</span></div><div class="vignettes">${vignettes.map((v,i)=>`<button class="vignette v${i}" data-vignette="${v.id}" data-tip="Load this example design and play three narrated scenes."><img class="scene-thumb" src="./media/${v.id}.jpg" alt="" width="112" height="62" decoding="async"><span class="vignettestory"><small>${v.tag} &nbsp;/&nbsp; 03 SCENES</small><strong>${v.name}</strong><span>${v.caption}</span></span><i>${icon('play',14)}</i></button>`).join('')}</div></section>`}
export function vignetteIntervals(id,sim){
 const v=vignettes.find(x=>x.id===id),ex=scenarios.find(x=>x.id===id);
 const event=ex.eventType?sim.events(0,Math.min(86400,sim.duration)).find(e=>e.type===ex.eventType&&ex.instant>=e.start&&ex.instant<e.end):null;
 if(v.id==='dawn-dusk'){const p=sim.at(3000).periodSec;return [[1200,1800],[1800,1800+p],[Math.min(sim.duration,86400)-p,Math.min(sim.duration,86400)]].map(([start,end],i)=>({id:v.chapter,label:v.frames[i],start,end,instant:start,camera:'orbit',status:'available'}))}
 if(!event)return [];
 const {start:a,end:b}=event,acq=Math.min(b,a+Math.max(1,sim.at(a+1).acquisitionSec||35));
 const bounds=id==='bulk-optical'?[[Math.max(1200,a-60),a],[a,acq],[acq,b+12]]:[[Math.max(1200,a-60),a],[a,b],[b,Math.min(sim.duration,b+300)]];
 return bounds.map(([start,end],i)=>({id:v.chapter,label:v.frames[i],start,end,instant:start,camera:ex.camera,status:'available',event:i===0?null:event}));
}
export {getExample};
export function narration(view,h,s,seg,sim){
 const f=h.fairing,c=chapters.find(x=>x.id===view.chapter)||chapters[0],v=vignettes.find(x=>x.id===view.vignette);
 const measure=(l,n,u,tip,d=1)=>metric(l,number(n,d),u,tip);
 const prop=()=>measure('Propellant',s.propellantKg,'kg','Fuel and oxidizer physically remaining aboard the spacecraft.',2);
 const soc=()=>measure('Battery charge',s.socPct,'%','Stored energy as a fraction of the pack’s present age-adjusted capacity.');
 const heat=()=>measure('Chip junction',s.junctionK,'K','Calculated chip junction temperature after heat flows into the cold plate and coolant.');
 const load=()=>measure('Compute load',s.itKW,'kW','Electrical power consumed by the compute trays at this instant.');
 let text='',metrics=[],title=c.title,camera=c.camera,tag='FLIGHT PLAN',page=c.page;
 if(v){title=v.frames[view.beat];tag=v.name.toUpperCase();camera=seg?.camera||'spacecraft';
 if(v.id==='bulk-optical'){text=['The recorder starts this example with 18 TB of bulk data. As Madrid rises above the elevation mask, the spacecraft can begin pointing its optical terminal.','The terminal slews toward Madrid and the fine-pointing loop acquires the receiver. Watch the electrical draw rise before useful bytes reach the ground.','The optical link carries queued files while the station remains in view. After the spacecraft loses contact, delivered goodput falls to zero and new data accumulates.'][view.beat];metrics=[measure('Recorder queue',s.queueGB/1000,'TB','Bulk files and output text still waiting for downlink.',3),measure('Useful downlink',s.goodputMbps,'Mbit/s','Application data that actually reaches the station.')];page='comm'}
 if(v.id==='compute-burst'){text=['The trays idle between scheduled bursts. Coolant still circulates through the enclosed bus and heat continues to leave the radiator faces.','Sixteen trays move into the active part of their duty cycle. Compute power rises first. The cold plates and coolant absorb heat as radiator temperature responds.','The workload ends and the trays return to idle. Stored heat continues to move through the loop. Compare chip junction temperature with its peak during the burst.'][view.beat];metrics=[load(),heat()];page='thermal'}
 if(v.id==='dawn-dusk'){text=['This inclined orbit follows the terminator at the chosen epoch. The Sun sits high above the orbital plane.','Follow the spacecraft around Earth. The orbit clears Earth’s shadow, so the solar array can keep generating even above the night side.','The first full day records zero seconds of eclipse. Compare generation with the active workload and watch what happens when the battery reaches its charge ceiling.'][view.beat];metrics=[measure('Solar beta',s.betaDeg,'°','Signed angle of the Sun above the current orbital plane.'),measure('Solar power',s.solarKW,'kW','Power delivered by the array at the current incidence and elapsed age.')];page='orbit'}
 }else switch(c.id){
 case 'integration':text=`The four solar wings fold into a cassette ahead of the insulated bus. Both radiator banks and the dish are latched before the ${number(h.launchKg/1000,2)} tonne stack mates to the ${h.launcherLabel.split(' · ')[0]} adapter. ${h.fit?'The folded assembly clears the modeled envelope.':'The folded assembly exceeds the modeled envelope.'}`;metrics=[measure('Stowed length',h.stowedLengthM,'m','Length of the stacked flight hardware and launch-only adapter.',2),measure('Radial clearance',f?.radialClearanceM??(h.input.fairingM-h.stowedDiameterM)/2,'m','Smallest radial gap between the stack and the tapered usable payload envelope. A negative gap means interference.',2)];break;
 case 'pad':text=`The spacecraft rides inside the ${h.launcherLabel.split(' · ')[0]} payload compartment. The wings remain stowed and the chemical tanks retain their launch inventory. The countdown ends at mission elapsed time zero.`;metrics=[measure('Launch mass',h.launchKg/1000,'t','Complete stack at liftoff, including the payload adapter.',2),prop()];break;
 case 'ascent':text='The launch vehicle supplies the ascent impulse. Follow the folded payload from the pad toward the insertion orbit. The plotted trajectory is an engineering illustration tied to the separation state.';metrics=[measure('Altitude',s.altitudeKm,'km','Altitude of the modeled launch stack above the spherical Earth.'),prop()];break;
 case 'insertion':text='The spacecraft separates from the upper stage. Its pressure-fed engines supply the trim impulse that brings it toward the operating orbit. Watch the tank inventory when the engines fire.';metrics=[measure('Delivered trim',s.trimPaidDv,'m/s','Velocity increment delivered by the spacecraft after separation.',2),prop()];break;
 case 'commissioning':text='The solar wings unfold, radiator banks swing clear of the insulated bus, and the joints orient the arrays toward the Sun. Solar power rises as cells become exposed. Compute service begins after deployment.';metrics=[measure('Deployment',100*s.deployment,'%','Fraction of the commanded appendage deployment completed.'),measure('Solar power',s.solarKW,'kW','Array output depends on unfolded area, illumination and Sun incidence.')];break;
 case 'operations':text=`Inside the six-wall enclosure, ${h.trays} compute trays share a pumped coolant loop. Cold plates carry the chip heat through bulkhead fittings to the external radiator banks. The cutaway reveals the installed equipment.`;metrics=[load(),heat()];break;
 case 'contact':text=s.station?`The spacecraft tracks ${s.station}. ${s.groundLink||'The payload terminal'} carries queued data once acquisition completes. Compare link goodput with the available recorder inventory.`:'Ahead of the pass, data accumulates in the recorder. At the ground station’s elevation mask the pointing system begins acquisition.';metrics=[measure('Downlink goodput',s.goodputMbps,'Mbit/s','Useful application bits received each second, limited by link capacity and queued bytes.'),measure('Queued payload',s.queueGB,'GB','Output text and bulk payload stored for downlink.',2)];break;
 case 'reboost':text='Drag removes orbital momentum between maintenance burns. The chemical engines fire prograde to repay the accumulated impulse. The consumed fuel and oxidizer are charged to this burn.';metrics=[measure('Total burn impulse',s.burnImpulseNs,'N·s','Cumulative impulse delivered by the spacecraft’s chemical engines.'),prop()];break;
 case 'desat':text='The CMG cluster has accumulated disturbance momentum. Magnetic coils work against the local field to unload it while the spacecraft holds attitude. Watch the momentum and coil power through the maneuver.';metrics=[measure('Stored momentum',s.momentumNms,'N·m·s','Momentum stored by the attitude-control cluster.'),measure('Coil power',s.coilKW*1000,'W','Electrical power drawn by the magnetic unloading coils.')];break;
 case 'deorbit':{const d=sim.disposal?.();text=`Payload service ends. A retrograde burn lowers perigee toward the entry corridor. ${d?.feasible===false?'The disposal plan has insufficient performance. Follow the achieved orbit and remaining inventory.':'Follow the burn, the lower perigee and the coast to the modeled entry interface.'}`;metrics=[measure('Perigee',s.perigeeKm,'km','Lowest altitude of the modeled post-burn orbit.'),measure('Disposal burn',s.disposalPaidDv??0,'m/s','Actual velocity change delivered by the retrograde disposal burn.',2)];break}
 }
 if(seg?.status==='infeasible'){const d=sim.disposal();title='Disposal limit reached';text=(d?.reason||'The selected hardware cannot complete the planned maneuver.')+'. The disposal ledger records the predicted requirement and the available propellant.';metrics=[measure('Required Δv',d?.requiredDv,'m/s','Retrograde velocity increment required by this disposal plan.'),prop()]}
 if(seg?.status==='unavailable'){text=seg.reason||'This operation has no qualifying event in the selected design’s modeled mission.';metrics=[]}
 return {title,text,metrics,tag,page,camera};
}
export function narrativePanel(view,h,s,seg,sim,playing,clock){
 const c=chapters.find(x=>x.id===view.chapter)||chapters[0],v=vignettes.find(x=>x.id===view.vignette),index=v?view.beat:chapters.indexOf(c),count=v?3:chapters.length;
 const n=narration(view,h,s,seg,sim),unavailable=seg?.status!=='available',last=index===count-1;
 return `<aside class="chaptercard"><div class="chapterkicker"><span class="guideflag">${escape(n.tag)}</span><span>${String(index+1).padStart(2,'0')} / ${String(count).padStart(2,'0')}</span></div><h2>${escape(n.title)}</h2><p>${escape(n.text)}</p>${(!h.fit||h.massMarginKg<0)&&c.id!=='integration'?'<div class="guidewarning">Concept study · this stack exceeds a single-launch constraint.</div>':''}<div class="chaptermetrics">${n.metrics.map(m=>`<div tabindex="0" data-tip="${escape(m.help)}"><small>${escape(m.label)}</small><strong>${escape(m.value)} <em>${escape(m.unit)}</em></strong></div>`).join('')}</div><button class="readmore" data-page="${n.page}" data-tip="Open the engineering workspace for this chapter at the same mission instant.">Inspect ${({launch:'fairing fit',orbit:'the orbit',power:'power',thermal:'heat flow',comm:'communications',prop:'propellant',attitude:'attitude control'})[n.page]||'telemetry'} ${icon('arrow-up-right',13)}</button><div class="chapterbuttons"><button class="btn guideplay" data-action="guideplay" ${unavailable&&!playing?'disabled':''} data-tip="Play or pause the guided sequence. Playback advances through real modeled events and skips the intervals between chapters.">${icon(playing?'pause':'play',13)} ${playing?'Pause':v?'Play vignette':'Play mission'}</button><button class="iconbtn" data-action="guidereplay" aria-label="Replay current scene">${icon('rotate-ccw',13)}</button><button class="iconbtn" data-action="guideback" aria-label="Previous scene" ${index===0?'disabled':''}>${icon('chevron-left',15)}</button><button class="iconbtn" data-action="guidenext" aria-label="${last?'Restart sequence':'Next scene'}">${icon(last?'rotate-ccw':'chevron-right',15)}</button></div><div class="guidemeter"><div><span>${escape(clock)}</span><span>${unavailable?'NO EVENT':'CHAPTER PROGRESS'}</span></div><input type="range" min="0" max="1000" step="1" id="guidecursor" aria-label="Scrub current chapter" ${unavailable?'disabled':''}></div></aside>`;
}

